// Concurrent state isolated by session_id.
const sessions = new Map(); // session_id -> Map(key -> value)

function isNonEmptyString(v) {
  return typeof v === 'string' && v.length > 0;
}

function isString(v) {
  return typeof v === 'string';
}

// Validate that args is a plain object containing exactly the required keys,
// each satisfying its type checker. Rejects missing, invalid, and extra args.
function validateArgs(args, spec) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments');
  }
  const required = Object.keys(spec);
  for (const k of Object.keys(args)) {
    if (!required.includes(k)) {
      throw new Error(`Unexpected argument: ${k}`);
    }
  }
  for (const k of required) {
    if (!(k in args)) {
      throw new Error(`Missing argument: ${k}`);
    }
    if (!spec[k](args[k])) {
      throw new Error(`Invalid argument: ${k}`);
    }
  }
}

export async function listTools() {
  return [
    {
      name: 'begin_session',
      description: 'Begin a new state-isolated session.',
      inputSchema: {
        type: 'object',
        properties: {
          session_id: { type: 'string' },
        },
        required: ['session_id'],
        additionalProperties: false,
      },
    },
    {
      name: 'put_value',
      description: 'Store a string value under a key for a session.',
      inputSchema: {
        type: 'object',
        properties: {
          session_id: { type: 'string' },
          key: { type: 'string' },
          value: { type: 'string' },
        },
        required: ['session_id', 'key', 'value'],
        additionalProperties: false,
      },
    },
    {
      name: 'get_value',
      description: 'Retrieve a value by key for a session.',
      inputSchema: {
        type: 'object',
        properties: {
          session_id: { type: 'string' },
          key: { type: 'string' },
        },
        required: ['session_id', 'key'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  if (name === 'begin_session') {
    validateArgs(args, { session_id: isNonEmptyString });
    sessions.set(args.session_id, new Map());
    return { content: [{ type: 'text', text: JSON.stringify({ ok: true, session_id: args.session_id }) }] };
  }

  if (name === 'put_value') {
    validateArgs(args, {
      session_id: isNonEmptyString,
      key: isNonEmptyString,
      value: isString,
    });
    if (!sessions.has(args.session_id)) {
      throw new Error('Session not found');
    }
    sessions.get(args.session_id).set(args.key, args.value);
    return { content: [{ type: 'text', text: JSON.stringify({ ok: true }) }] };
  }

  if (name === 'get_value') {
    validateArgs(args, {
      session_id: isNonEmptyString,
      key: isNonEmptyString,
    });
    if (!sessions.has(args.session_id)) {
      throw new Error('Session not found');
    }
    const store = sessions.get(args.session_id);
    if (!store.has(args.key)) {
      throw new Error('Key not found');
    }
    const value = store.get(args.key);
    return { content: [{ type: 'text', text: JSON.stringify({ value }) }] };
  }

  throw new Error('Unknown tool');
}

